export function computeOrientationPCA(mask,width,height){let count=0;let sumX=0;let sumY=0;for(let y=0;y<height;y++){const rowOffset=y*width;for(let x=0;x<width;x++){if(mask[rowOffset+x]>=128){sumX+=x;sumY+=y;count++}}}if(count<20){return{angleRad:0,angleDeg:0,centroid:{x:width/2,y:height/2},count:count,valid:false}}const cx=sumX/count;const cy=sumY/count;let mu20=0;let mu02=0;let mu11=0;for(let y=0;y<height;y++){const rowOffset=y*width;const dy=y-cy;for(let x=0;x<width;x++){if(mask[rowOffset+x]>=128){const dx=x-cx;mu20+=dx*dx;mu02+=dy*dy;mu11+=dx*dy}}}const angleRad=.5*Math.atan2(2*mu11,mu20-mu02);const angleDeg=angleRad*180/Math.PI;return{angleRad:angleRad,angleDeg:angleDeg,centroid:{x:cx,y:cy},count:count,valid:true}}export function createCanvas(width,height){if(typeof OffscreenCanvas!=="undefined"){return new OffscreenCanvas(width,height)}if(typeof document!=="undefined"&&document.createElement){const c=document.createElement("canvas");c.width=width;c.height=height;return c}throw new Error("Môi trường không hỗ trợ Canvas hoặc OffscreenCanvas.")}export function alignAndPadCanvas(source,angleRad,targetSize=448,paddingRatio=.12){const sw=source.width;const sh=source.height;const diag=Math.ceil(Math.hypot(sw,sh));const rotCanvas=createCanvas(diag,diag);const rctx=rotCanvas.getContext("2d",{willReadFrequently:true});rctx.fillStyle="#000000";rctx.fillRect(0,0,diag,diag);rctx.save();rctx.translate(diag/2,diag/2);rctx.rotate(-angleRad);rctx.drawImage(source,-sw/2,-sh/2);rctx.restore();const imgData=rctx.getImageData(0,0,diag,diag);const d=imgData.data;let minX=diag,minY=diag,maxX=-1,maxY=-1;let fgCount=0;for(let y=0;y<diag;y++){const rowOffset=y*diag;for(let x=0;x<diag;x++){const idx=(rowOffset+x)*4;const isFg=(d[idx]>20||d[idx+1]>20||d[idx+2]>20)&&d[idx+3]>40;if(isFg){fgCount++;if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y}}}if(fgCount===0||maxX<minX||maxY<minY){minX=0;minY=0;maxX=diag-1;maxY=diag-1}const bw=maxX-minX+1;const bh=maxY-minY+1;const outCanvas=createCanvas(targetSize,targetSize);const octx=outCanvas.getContext("2d",{willReadFrequently:true});octx.fillStyle="#000000";octx.fillRect(0,0,targetSize,targetSize);const maxInnerSide=Math.round(targetSize*(1-paddingRatio*2));const scale=Math.min(maxInnerSide/bw,maxInnerSide/bh,1);const drawW=Math.round(bw*scale);const drawH=Math.round(bh*scale);const dstX=Math.round((targetSize-drawW)/2);const dstY=Math.round((targetSize-drawH)/2);octx.imageSmoothingEnabled=true;octx.imageSmoothingQuality="high";octx.drawImage(rotCanvas,minX,minY,bw,bh,dstX,dstY,drawW,drawH);return{canvas:outCanvas,bbox:{minX:minX,minY:minY,width:bw,height:bh},rotatedAngleDeg:-angleRad*180/Math.PI}}